package com.bank.engines.batch;

import com.bank.engines.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// BATCH: one run over the whole bounded dataset.
public class BatchEngine {
    private static final Logger log = Logger.getLogger(BatchEngine.class.getName());

    public Map<String, BigDecimal> run(List<Txn> bounded) {
        log.info("BATCH run over " + bounded.size() + " rows (one scheduled pass)");
        Map<String, BigDecimal> totals = new LinkedHashMap<>();
        for (Txn t : bounded) totals.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
        return totals;
    }
}
