package com.bank.engines.microbatch;

import com.bank.engines.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// MICRO-BATCH (Spark Structured Streaming style): process small fixed stacks continuously.
public class MicroBatchEngine {
    private static final Logger log = Logger.getLogger(MicroBatchEngine.class.getName());
    private final int batchSize;
    private final Map<String, BigDecimal> runningTotals = new LinkedHashMap<>();

    public MicroBatchEngine(int batchSize) { this.batchSize = batchSize; }

    public void ingest(List<Txn> stream) {
        List<Txn> buffer = new ArrayList<>();
        int batchNo = 0;
        for (Txn t : stream) {
            buffer.add(t);
            if (buffer.size() == batchSize) { batchNo++; processBatch(buffer, batchNo); buffer.clear(); }
        }
        if (!buffer.isEmpty()) processBatch(buffer, ++batchNo);
    }

    private void processBatch(List<Txn> micro, int batchNo) {
        for (Txn t : micro) runningTotals.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
        log.info("MICRO-BATCH #" + batchNo + " processed " + micro.size()
                + " rows (latency floor ~ trigger interval), running=" + runningTotals);
    }
}
