package com.bank.engines.record;

import com.bank.engines.model.Txn;
import java.math.BigDecimal;
import java.util.logging.Logger;

// RECORD-AT-A-TIME (Flink style): handle each event the instant it arrives.
public class RecordAtATimeEngine {
    private static final Logger log = Logger.getLogger(RecordAtATimeEngine.class.getName());
    private final BigDecimal fraudThreshold;

    public RecordAtATimeEngine(BigDecimal fraudThreshold) { this.fraudThreshold = fraudThreshold; }

    public void onEvent(Txn t) {
        if (t.getAmount().compareTo(fraudThreshold) > 0) {
            log.severe(() -> "RECORD-AT-A-TIME low-latency ALERT: " + t.getAccountId()
                    + " " + t.getAmount() + " (acted instantly)");
        } else {
            log.info(() -> "RECORD-AT-A-TIME ok: " + t.getAccountId() + " " + t.getAmount());
        }
    }
}
