package com.bank.engines;

import com.bank.engines.batch.BatchEngine;
import com.bank.engines.microbatch.MicroBatchEngine;
import com.bank.engines.model.Txn;
import com.bank.engines.record.RecordAtATimeEngine;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class EngineDemo {
    private static final Logger log = Logger.getLogger(EngineDemo.class.getName());

    public static void main(String[] args) {
        List<Txn> data = List.of(
            new Txn("SAV2001", new BigDecimal("1200")),
            new Txn("CUR3001", new BigDecimal("150000")),
            new Txn("SAV2001", new BigDecimal("800")),
            new Txn("CUR3001", new BigDecimal("5000")),
            new Txn("SAV2001", new BigDecimal("300"))
        );

        log.info("=== BATCH ENGINE (whole day, one run) ===");
        new BatchEngine().run(data).forEach((a, t) -> log.info(a + " = " + t));

        log.info("=== MICRO-BATCH ENGINE (small continuous stacks) ===");
        new MicroBatchEngine(2).ingest(data);

        log.info("=== RECORD-AT-A-TIME ENGINE (instant per event) ===");
        RecordAtATimeEngine flink = new RecordAtATimeEngine(new BigDecimal("100000"));
        data.forEach(flink::onEvent);
    }
}
